delete from rtks_role_skill_relation
where skill_id in

    #{skillId}

mapper.select:
select skill_id as resource_id, weight
from rtks_role_skill_relation
where role_id = #{roleId}

select rtks_role_skill_relation.role_id as role_id, count(distinct rtks_role_skill_relation.skill_id) as skill_count, count(distinct rtks_skill_mission_relation.mission_template_id) as mission_count from rtks_role_skill_relation left join rtks_skill on rtks_role_skill_relation.skill_id = rtks_skill.resource_id left join rtks_skill_mission_relation on rtks_skill.resource_id = rtks_skill_mission_relation.skill_id where rtks_role_skill_relation.role_id in
#{roleId}
group by rtks_role_skill_relation.role_id
